var settingNames = []string{"layering", "width", "promotion", "heuristic", "sweeps", "node_sep", "dummy_sep", "layer_gap", "direction", "sifting", "reduce", "restarts", "seed"}
type Settings struct {
	Layering, Promotion, Heuristic, Direction, Sifting, Reduce string
	Width, Sweeps, NodeSep, DummySep, LayerGap, Restarts       int
	Seed                                                       int64
}
func defaultSettings() Settings {
	return Settings{Layering: "longest", Width: 4, Promotion: "off", Heuristic: "barycenter", Sweeps: 12, NodeSep: 2, DummySep: 1, LayerGap: 3, Direction: "TB", Sifting: "off", Reduce: "off", Seed: 1}
}
func (s Settings) Values() []string {
	return []string{s.Layering, strconv.Itoa(s.Width), s.Promotion, s.Heuristic, strconv.Itoa(s.Sweeps), strconv.Itoa(s.NodeSep), strconv.Itoa(s.DummySep), strconv.Itoa(s.LayerGap), s.Direction, s.Sifting, s.Reduce, strconv.Itoa(s.Restarts), strconv.FormatInt(s.Seed, 10)}
}
var integerWord = regexp.MustCompile(`^[0-9]{1,10}$`)
func (s *Settings) Set(name, value string) bool {
	options := map[string][]string{"layering": {"longest", "coffman"}, "promotion": {"on", "off"}, "heuristic": {"barycenter", "median"}, "direction": {"TB", "BT", "LR", "RL"}, "sifting": {"on", "off"}, "reduce": {"on", "off"}}
	if choices, ok := options[name]; ok {
		if !slices.Contains(choices, value) {
			return false
		}
		switch name {
		case "layering":
			s.Layering = value
		case "promotion":
			s.Promotion = value
		case "heuristic":
			s.Heuristic = value
		case "direction":
			s.Direction = value
		case "sifting":
			s.Sifting = value
		case "reduce":
			s.Reduce = value
		}
		return true
	}
	ranges := map[string][2]int64{"width": {1, 40}, "sweeps": {0, 50}, "node_sep": {1, 9}, "dummy_sep": {1, 9}, "layer_gap": {2, 9}, "restarts": {0, 9}, "seed": {1, 2147483646}}
	bounds, ok := ranges[name]
	if !ok || !integerWord.MatchString(value) {
		return false
	}
	number, _ := strconv.ParseInt(value, 10, 64)
	if number < bounds[0] || number > bounds[1] {
		return false
	}
	switch name {
	case "width":
		s.Width = int(number)
	case "sweeps":
		s.Sweeps = int(number)
	case "node_sep":
		s.NodeSep = int(number)
	case "dummy_sep":
		s.DummySep = int(number)
	case "layer_gap":
		s.LayerGap = int(number)
	case "restarts":
		s.Restarts = int(number)
	case "seed":
		s.Seed = number
	}
	return true
}
type NodeData struct {
	ID    int
	Label string
}
type RawEdge struct{ From, To int }
type Block struct {
	Name                                    string
	Settings                                Settings
	Nodes                                   []NodeData
	Edges                                   []RawEdge
	HasPath                                 bool
	PathFrom, PathTo, SelfLoops, Duplicates int
	Error                                   string
	ErrorLine                               int
}
func readBlocks() []*Block {
	defaults := defaultSettings()
	for _, line := range lines("input/params.txt") {
		if ignored(line) {
			continue
		}
		a := strings.Split(line, " ")
		defaults.Set(a[0], a[1])
	}
	out := []*Block{}
	var block *Block
	declared := map[int]bool{}
	accepted := map[[2]int]bool{}
	for index, line := range lines("input/graphs.txt") {
		if ignored(line) {
			continue
		}
		a := strings.Split(line, " ")
		if a[0] == "GRAPH" {
			block = &Block{Name: a[1], Settings: defaults}
			out = append(out, block)
			declared = map[int]bool{}
			accepted = map[[2]int]bool{}
			continue
		}
		if block.Error != "" {
			continue
		}
		reason := ""
		switch a[0] {
		case "OPTION":
			if !block.Settings.Set(a[1], a[2]) {
				reason = "bad_option"
			}
		case "NODE":
			id := integer(a[1])
			if declared[id] {
				reason = "duplicate_node"
			} else if len(block.Nodes) == 40 {
				reason = "too_many_nodes"
			} else {
				declared[id] = true
				block.Nodes = append(block.Nodes, NodeData{id, a[2]})
			}
		case "EDGE":
			from, to := integer(a[1]), integer(a[2])
			if !declared[from] || !declared[to] {
				reason = "unknown_node"
			} else if from == to {
				block.SelfLoops++
			} else if accepted[[2]int{from, to}] {
				block.Duplicates++
			} else {
				accepted[[2]int{from, to}] = true
				block.Edges = append(block.Edges, RawEdge{from, to})
			}
		case "END":
			if len(block.Nodes) == 0 {
				reason = "no_nodes"
			}
		}
		if reason != "" {
			block.Error = reason
			block.ErrorLine = index + 1
		}
	}
	for _, b := range out {
		sort.Slice(b.Nodes, func(i, j int) bool { return b.Nodes[i].ID < b.Nodes[j].ID })
	}
	return out
}
func integer(s string) int {
	n, e := strconv.Atoi(s)
	if e != nil {
		panic(e)
	}
	return n
}
func lines(path string) []string {
	b, e := os.ReadFile(path)
	if e != nil {
		panic(e)
	}
	if len(b) == 0 {
		return nil
	}
	return strings.Split(strings.TrimSuffix(string(b), "\n"), "\n")
}
func ignored(s string) bool { return s == "" || s[0] == '#' }
func acyclic(n int, edges []*Edge) []int {
	remaining := make([]bool, n)
	for i := range remaining {
		remaining[i] = true
	}
	head, tail := []int{}, []int{}
	for count := 0; count < n; count++ {
		in, out := make([]int, n), make([]int, n)
		for _, e := range edges {
			if remaining[e.From] && remaining[e.To] {
				out[e.From]++
				in[e.To]++
			}
		}
		chosen := -1
		toTail := false
		for v := 0; v < n; v++ {
			if remaining[v] && out[v] == 0 {
				chosen = v
				toTail = true
				break
			}
		}
		if chosen < 0 {
			for v := 0; v < n; v++ {
				if remaining[v] && in[v] == 0 {
					chosen = v
					break
				}
			}
		}
		if chosen < 0 {
			for v := 0; v < n; v++ {
				if remaining[v] && (chosen < 0 || out[v]-in[v] > out[chosen]-in[chosen]) {
					chosen = v
				}
			}
		}
		remaining[chosen] = false
		if toTail {
			tail = append([]int{chosen}, tail...)
		} else {
			head = append(head, chosen)
		}
	}
	return append(head, tail...)
}
type Promotion struct{ Round, Node, Diff int }
type LayeringResult struct {
	Height, Labels        []int
	DummiesBefore, Rounds int
	Promotions            []Promotion
}
func assignLayers(n int, predecessors, successors [][]int, settings Settings) *LayeringResult {
	r := &LayeringResult{Height: make([]int, n), Labels: make([]int, n)}
	if settings.Layering == "longest" {
		known := make([]bool, n)
		var height func(int) int
		height = func(v int) int {
			if known[v] {
				return r.Height[v]
			}
			for _, w := range successors[v] {
				r.Height[v] = max(r.Height[v], height(w)+1)
			}
			known[v] = true
			return r.Height[v]
		}
		for v := 0; v < n; v++ {
			height(v)
		}
	} else {
	}
	for v := 0; v < n; v++ {
		for _, w := range successors[v] {
			r.DummiesBefore += r.Height[v] - r.Height[w] - 1
		}
	}
	if settings.Promotion == "on" {
	}
	return r
}
func positions(orders [][]int, count int) []int {
	out := make([]int, count)
	for _, row := range orders {
		for i, v := range row {
			out[v] = i
		}
	}
	return out
}
func gapCrossings(segments []Segment, indices []int, pos []int, width int) int {
	pairs := make([][2]int, len(indices))
	for i, index := range indices {
		s := segments[index]
		pairs[i] = [2]int{pos[s.Upper], pos[s.Lower]}
	}
	sort.Slice(pairs, func(i, j int) bool {
		a, b := pairs[i], pairs[j]
		if a[0] != b[0] {
			return a[0] < b[0]
		}
		return a[1] < b[1]
	})
	capacity := 1
	for capacity < width {
		capacity *= 2
	}
	tree := make([]int, 2*capacity-1)
	crossings := 0
	for _, pair := range pairs {
		k := pair[1] + capacity - 1
		tree[k]++
		for k > 0 {
			if k%2 == 1 {
				crossings += tree[k+1]
			}
			k = (k - 1) / 2
			tree[k]++
		}
	}
	return crossings
}
func totalCrossings(g *Layout, orders [][]int) int {
	pos := positions(orders, len(g.Vertices))
	sum := 0
	for i, indices := range g.Gaps {
		sum += gapCrossings(g.Segments, indices, pos, len(orders[i+1]))
	}
	return sum
}
func bruteCrossings(g *Layout, orders [][]int, countEdges bool) int {
	pos := positions(orders, len(g.Vertices))
	sum := 0
	for _, indices := range g.Gaps {
		for i, index := range indices {
			a := g.Segments[index]
			for _, other := range indices[i+1:] {
				b := g.Segments[other]
				if (pos[a.Upper]-pos[b.Upper])*(pos[a.Lower]-pos[b.Lower]) < 0 {
					sum++
					if countEdges {
						g.Edges[a.Edge].Crossings++
						g.Edges[b.Edge].Crossings++
					}
				}
			}
		}
	}
	return sum
}
func adjacentCost(g *Layout, v, w int, pos []int) int {
	count := 0
	for side := 0; side < 2; side++ {
		a, b := g.Vertices[v].Upper, g.Vertices[w].Upper
		if side == 1 {
			a, b = g.Vertices[v].Lower, g.Vertices[w].Lower
		}
		for _, u := range a {
			for _, q := range b {
				if pos[u] > pos[q] {
					count++
				}
			}
		}
	}
	return count
}
type BKVariant struct {
	Name                     string
	Root, Aligned            []int
	Blocks, Width, Low, High int
}
type Coordinates struct {
	Marked   map[[2]int]bool
	Variants []BKVariant
	Smallest int
}
func floorDiv(a, b int) int {
	q := a / b
	if a < 0 && a%b != 0 {
		q--
	}
	return q
}
func coordinates(g *Layout) *Coordinates {
	result := &Coordinates{Marked: map[[2]int]bool{}}
	count := len(g.Vertices)
	pos := positions(g.Orders, count)
	}
	for v := 0; v < count; v++ {
		values := []int{}
		for _, variant := range result.Variants {
			values = append(values, variant.Aligned[v])
		}
		slices.Sort(values)
		g.Vertices[v].X = floorDiv(values[1]+values[2], 2)
	}
	minimum := g.Vertices[0].X - g.Vertices[0].Left
	for _, v := range g.Vertices {
		minimum = min(minimum, v.X-v.Left)
	}
	for _, v := range g.Vertices {
		v.X -= minimum
	}
	return result
}
type Cell struct{ Row, Column int }
type Canvas struct {
	M, N, Rows, Columns int
	Direction           string
	Lines               [][]byte
	Arrows, Boxes       [][]byte
	Highlighted         [][]bool
}
func newCanvas(m, n int, direction string) *Canvas {
	rows, columns := m, n
	if direction == "LR" || direction == "RL" {
		rows, columns = n, m
	}
	c := &Canvas{M: m, N: n, Rows: rows, Columns: columns, Direction: direction, Lines: make([][]byte, rows), Arrows: make([][]byte, rows), Boxes: make([][]byte, rows), Highlighted: make([][]bool, rows)}
	for r := 0; r < rows; r++ {
		c.Lines[r] = make([]byte, columns)
		c.Arrows[r] = make([]byte, columns)
		c.Boxes[r] = make([]byte, columns)
		c.Highlighted[r] = make([]bool, columns)
	}
	return c
}
func (c *Canvas) Map(main, secondary int) Cell {
	if c.Direction == "BT" || c.Direction == "RL" {
		main = c.M - 1 - main
	}
	if c.Direction == "TB" || c.Direction == "BT" {
		return Cell{main, secondary}
	}
	return Cell{secondary, main}
}
func (c *Canvas) Line(main, secondary int, kind byte) {
	p := c.Map(main, secondary)
	c.Lines[p.Row][p.Column] |= kind
}
func (c *Canvas) MainLine(main, secondary int) {
	kind := byte(1)
	if c.Direction == "LR" || c.Direction == "RL" {
		kind = 2
	}
	c.Line(main, secondary, kind)
}
func (c *Canvas) SecondaryLine(main, secondary int) {
	kind := byte(2)
	if c.Direction == "LR" || c.Direction == "RL" {
		kind = 1
	}
	c.Line(main, secondary, kind)
}
func (c *Canvas) Segment(g0, gap, upper, lower, offset int) {
	if upper == lower {
		for j := 0; j < gap; j++ {
			c.MainLine(g0+j, upper)
		}
		return
	}
	for j := 0; j < offset; j++ {
		c.MainLine(g0+j, upper)
	}
	c.Line(g0+offset, upper, 4)
	c.Line(g0+offset, lower, 4)
	for x := min(upper, lower) + 1; x < max(upper, lower); x++ {
		c.SecondaryLine(g0+offset, x)
	}
	for j := offset + 1; j < gap; j++ {
		c.MainLine(g0+j, lower)
	}
}
func (c *Canvas) CrossingCells() int {
	sum := 0
	for _, row := range c.Lines {
		for _, mask := range row {
			if mask&3 == 3 {
				sum++
			}
		}
	}
	return sum
}
func (c *Canvas) Character(r, column int) byte {
	if c.Boxes[r][column] != 0 {
		return c.Boxes[r][column]
	}
	if c.Arrows[r][column] != 0 {
		return c.Arrows[r][column]
	}
	if c.Highlighted[r][column] {
		return '#'
	}
	switch c.Lines[r][column] {
	case 0:
		return ' '
	case 1:
		return '|'
	case 2:
		return '-'
	default:
		return '+'
	}
}
func (c *Canvas) Drawing(name string) []string {
	ruler := "    "
	for column := 0; column < c.Columns; column++ {
		ruler += fmt.Sprintf("%d", column%10)
	}
	out := []string{fmt.Sprintf("graph %s %dx%d", name, c.Columns, c.Rows), ruler}
	for r := 0; r < c.Rows; r++ {
		row := make([]byte, c.Columns)
		for column := range row {
			row[column] = c.Character(r, column)
		}
		out = append(out, strings.TrimRight(fmt.Sprintf("%3d %s", r, row), " "))
	}
	return out
}
